// argparse-compatible CLI layer for test13_executable.
// Zero-dependency, ESM, no RegExp — all matching done by explicit char scanning.

const LONG_OPTIONS = ['--help', '--a', '--b', '--c'];

function usageLine(prog) {
  return 'usage: ' + prog + ' [-h] --a A --b B --c C';
}

export function formatHelp(prog = 'test13_executable') {
  return usageLine(prog) + '\n' +
    '\n' +
    'Markdown with extension configuration\n' +
    '\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n' +
    '  --b B\n' +
    '  --c C';
}

export function handleCliError(message, prog = 'test13_executable') {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(prog + ': error: ' + message + '\n');
  return { action: 'exit', code: 2 };
}

function isAsciiDigit(ch) {
  return ch >= '0' && ch <= '9';
}

function isAllDigits(s) {
  for (let i = 0; i < s.length; i++) {
    if (!isAsciiDigit(s[i])) return false;
  }
  return true;
}

// Mirrors argparse's _negative_number_matcher: ^-\d+$ | ^-\d*\.\d+$
function looksLikeNegativeNumber(token) {
  if (token.length < 2 || token[0] !== '-') return false;
  const rest = token.slice(1);
  if (rest.length > 0 && isAllDigits(rest)) return true;
  const dot = rest.indexOf('.');
  if (dot === -1) return false;
  const intPart = rest.slice(0, dot);
  const fracPart = rest.slice(dot + 1);
  return isAllDigits(intPart) && fracPart.length > 0 && isAllDigits(fracPart);
}

// A token argparse would treat as an option string rather than a value.
function isOptionLike(token) {
  if (token.length === 0 || token[0] !== '-') return false;
  if (token === '-') return false;
  if (looksLikeNegativeNumber(token)) return false;
  return true;
}

// Exact match, else unambiguous prefix (argparse allow_abbrev). Returns the
// canonical option string or null when unknown.
function matchLongOption(name) {
  for (const opt of LONG_OPTIONS) {
    if (opt === name) return opt;
  }
  let found = null;
  for (const opt of LONG_OPTIONS) {
    if (opt.length > name.length && opt.startsWith(name)) {
      if (found !== null) return null; // ambiguous — unreachable with this option set
      found = opt;
    }
  }
  return found;
}

export function parseCliArgs(argv, prog = 'test13_executable') {
  const values = { a: undefined, b: undefined, c: undefined };
  const extras = [];
  let i = 0;

  while (i < argv.length) {
    const token = argv[i];

    if (token === '--') {
      // Separator: everything from here on (including '--' itself) is extra,
      // matching the observed Python 3.13 argparse behavior.
      while (i < argv.length) {
        extras.push(argv[i]);
        i++;
      }
      break;
    }

    if (token.length > 2 && token[0] === '-' && token[1] === '-') {
      // Long option, possibly with =value.
      let name = token;
      let explicit = null;
      const eq = token.indexOf('=');
      if (eq !== -1) {
        name = token.slice(0, eq);
        explicit = token.slice(eq + 1);
      }
      const matched = matchLongOption(name);
      if (matched === '--help') {
        if (explicit !== null) {
          return handleCliError(
            "argument -h/--help: ignored explicit argument '" + explicit + "'",
            prog
          );
        }
        process.stdout.write(formatHelp(prog) + '\n');
        return { action: 'exit', code: 0 };
      }
      if (matched === '--a' || matched === '--b' || matched === '--c') {
        const dest = matched[2];
        if (explicit !== null) {
          values[dest] = explicit;
          i++;
          continue;
        }
        const next = i + 1 < argv.length ? argv[i + 1] : null;
        if (next === null || isOptionLike(next)) {
          return handleCliError(
            'argument ' + matched + ': expected one argument',
            prog
          );
        }
        values[dest] = next;
        i += 2;
        continue;
      }
      // Unknown long option: collect verbatim, do not consume a value.
      extras.push(token);
      i++;
      continue;
    }

    if (isOptionLike(token)) {
      // Short option cluster. '-h...' fires help immediately (argparse runs
      // the help action as soon as -h is consumed).
      if (token[1] === 'h') {
        process.stdout.write(formatHelp(prog) + '\n');
        return { action: 'exit', code: 0 };
      }
      extras.push(token);
      i++;
      continue;
    }

    // Bare '-', negative numbers, and plain words are extra positionals.
    extras.push(token);
    i++;
  }

  const missing = [];
  if (values.a === undefined) missing.push('--a');
  if (values.b === undefined) missing.push('--b');
  if (values.c === undefined) missing.push('--c');
  if (missing.length > 0) {
    return handleCliError(
      'the following arguments are required: ' + missing.join(', '),
      prog
    );
  }

  if (extras.length > 0) {
    return handleCliError('unrecognized arguments: ' + extras.join(' '), prog);
  }

  return { action: 'run', args: { a: values.a, b: values.b, c: values.c } };
}

// Temporary differential harness: run parseCliArgs like the entry would.
import { parseCliArgs } from '/output/lib/cli.mjs';
const result = parseCliArgs(process.argv.slice(2));
if (result.action === 'exit') {
  process.exit(result.code);
}
// action === 'run': emit a stable marker so the harness can compare args.
process.stdout.write('RUN a=' + JSON.stringify(result.args.a) +
  ' b=' + JSON.stringify(result.args.b) +
  ' c=' + JSON.stringify(result.args.c) + '\n');

