// of candidate option strings in definition order; empty means unknown.
function matchLongOption(name) {
  for (const opt of LONG_OPTIONS) {
    if (opt === name) return [opt];
  }
  const found = [];
  for (const opt of LONG_OPTIONS) {
    if (opt.length > name.length && opt.startsWith(name)) found.push(opt);
